// One output item per tender: buyer, deadline, place of performance, number of GAEB positions and the
// bill-of-quantities positions whose short/long text matched your keywords (with a text snippet).
const SNIPPET = 160; // characters of context around the keyword

function snippet(text, keyword) {
  if (!text) return '';
  const flat = text.replace(/\s+/g, ' ');
  const i = flat.toLowerCase().indexOf(keyword.toLowerCase());
  if (i < 0) return flat.slice(0, SNIPPET);
  const start = Math.max(0, i - SNIPPET / 2);
  return (start > 0 ? '…' : '') + flat.slice(start, start + SNIPPET) + (start + SNIPPET < flat.length ? '…' : '');
}

const out = [];
for (const { json: t } of $input.all()) {
  if (!t.title) continue; // empty run
  const byOz = new Map((t.positions || []).map((p) => [p.oz, p]));
  const hits = (t.keywordPositionHits || []).map((h) => {
    const p = byOz.get(h.oz) || {};
    const kw = h.keywords[0];
    return {
      oz: h.oz,
      keywords: h.keywords.join(', '),
      shortText: p.shortText || '',
      quantity: p.quantity ?? null,
      unit: p.unit || '',
      excerpt: snippet(p.longText || p.shortText, kw),
    };
  });
  const loc = t.location || {};
  const place = [loc.postalCode, loc.city].filter(Boolean).join(' ') || loc.region || 'n/a';
  const deadline = t.submissionDeadline
    ? new Date(t.submissionDeadline).toLocaleString('de-DE', { timeZone: 'Europe/Berlin' })
    : 'n/a';
  const lines = hits.slice(0, 5).map(
    (h) => `  • OZ ${h.oz}: ${h.shortText} (${h.quantity ?? '?'} ${h.unit}) – „${h.excerpt}“`,
  );
  out.push({
    json: {
      title: t.title,
      buyer: t.buyer?.name || 'n/a',
      deadline,
      deadlineType: t.deadlineType,
      place,
      gaebPositions: t.positionCount,
      matchedKeywords: (t.matchedKeywords || []).join(', '),
      keywordHits: hits,
      documentsUrl: t.documentsUrl,
      message: [
        `🏗️ ${t.title}`,
        `Vergabestelle / Buyer: ${t.buyer?.name || 'n/a'}`,
        `Frist / Deadline: ${deadline} · Ort / Place: ${place}`,
        `GAEB-Positionen / BoQ positions: ${t.positionCount} · Keywords: ${(t.matchedKeywords || []).join(', ') || '–'}`,
        ...lines,
        `Unterlagen / Documents: ${t.documentsUrl}`,
      ].join('\n'),
    },
  });
}
return out;
